-- Configuration Guide: https://wiki.hypr.land/Configuring/

-- Load user modules from ~/.config and Cozy defaults from $COZY_PATH.
package.path = os.getenv("HOME")
  .. "/.config/?.lua;"
  .. (os.getenv("COZY_PATH") or os.getenv("COZY_DIR") or (os.getenv("HOME") .. "/.local/share/Cozy"))
  .. "/?.lua;"
  .. package.path

-- --- 1. Cozy System Defaults (Do Not Edit) ---
require("default.hypr.cozy")

-- --- 2. Personal Overrides (User Settings) ---
-- These files overwrite the defaults loaded above.
require("hypr.monitors")
require("hypr.envs")
require("hypr.input")
require("hypr.looknfeel")
require("hypr.animations")
require("hypr.bindings")
require("hypr.rules")
require("hypr.autostart")
require("hypr.gestures")
require("hypr.plugins")

-- --- 4. Optional machine-local overrides (generated by install scripts) ---
pcall(require, "hypr.envs.local")
pcall(require, "hypr.monitors.local")

-- --- 3. Toggle config flags dynamically ---
require("default.hypr.toggles")

-- Match the cursor override from the active Spice configuration.
hl.env("XCURSOR_THEME", "Bibata-Original-Classic")
hl.env("HYPRCURSOR_THEME", "Bibata-Original-Classic")
hl.env("XCURSOR_SIZE", "28")
hl.env("HYPRCURSOR_SIZE", "28")
